"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["41948"],{21763(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>l,frontMatter:()=>r,contentTitle:()=>c,toc:()=>h,assets:()=>a});var i=JSON.parse('{"id":"democracy","title":"","description":"2006/4/20 2214","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/democracy.md","sourceDirName":".","slug":"/democracy","permalink":"/en/democracy","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"democracy","title":"","hide_table_of_contents":true,"sidebar_label":"Democracy: The Condom of Politics! (2006/4/20 22:04:14)"},"sidebar":"timelineSidebar","previous":{"title":"Bush: The Great Savior of Today\'s World! (2006/4/19 21:42:50)","permalink":"/en/timeline/confucius/20060419"},"next":{"title":"From the Leftists\' Brazen Lies About \'Great Savior,\' We See the Left\'s Days Are Numbered! (2006/4/21 16:40:39)","permalink":"/en/timeline/economics/saviour1"}}'),o=t(74848),s=t(28453);let r={id:"democracy",title:"",hide_table_of_contents:!0,sidebar_label:"Democracy: The Condom of Politics! (2006/4/20 22:04:14)"},c="Democracy: The Condom of Politics!",a={},h=[];function d(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"democracy-the-condom-of-politics",children:"Democracy: The Condom of Politics!"})}),"\n",(0,o.jsxs)(n.blockquote,{children:["\n",(0,o.jsx)(n.p,{children:"2006/4/20 22:04:14"}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Politics is the promiscuity of interest. Democracy is to politics what the condom is to promiscuity. Promiscuity is human nature; interest is the nature of man. A person out in the wild, then in the bedroom with a condom -- this is interest serving time. Politics, from non-action to despotism to democracy -- this is time serving interest. Interest serving time, time serving interest, human nature and the nature of man -- herein lies politics. Democracy as the condom of politics -- is this not the interplay of time and interest?"}),"\n",(0,o.jsx)(n.p,{children:"The benefit of the condom is twofold: preventing pregnancy and preventing disease. If everyone strictly observed so-called monogamy, seeking not the pleasures of the bed but only the continuation of the family line, then the condom would have no reason to exist. Yet this principle is not a real principle -- the absence of principle becomes the inevitable principle. To disguise it with the mandate of heaven is the delusion of charlatans deceiving the world. No such person exists in this world, nor does such a principle. Heavenly principle cannot be divorced from human nature. To seek heavenly principle apart from human nature produces only delusion. People always have desire, but human desire is inconstant -- when times change, so does desire, and do times ever stay the same? Thus the condom serves people and their nature; people do not serve the condom to have their nature."}),"\n",(0,o.jsx)(n.p,{children:"For human desire cannot be confined by delusional heavenly principles. The condom stands neither inside principle nor outside interest. When interest serves time and becomes politics, democracy is not the heavenly principle of politics -- when times change, interest changes, and when interest changes, principle changes. Time is not a fixed thing -- how can it be singular? To confine time within principle and principle within desire -- equally delusional. For time is merely the interplay of human nature, and there is nothing beyond interest!"}),"\n",(0,o.jsx)(n.p,{children:"The condom to people is interest; democracy to politics, likewise. Interest is never constant, people never constant, and democracy in politics is no different. Since there is not just one kind of person in the world, there need not be just one kind of condom; since there is not just one kind of politics in the world, there need not be just one kind of democracy. The quality of a condom has nothing to do with size -- it need only suit its user. The quality of democracy has nothing to do with whether it's Chinese or foreign -- it need only suit its politics. The Han and Tang dynasties had their own forms of democracy; antiquity had its own forms of contraception. Must a condom necessarily be a rubber sheath?"})]})}function l(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>c});var i=t(96540);let o={},s=i.createContext(o);function r(e){let n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function c(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);